package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId   string          // PIC X(5) @0 len=5
	ErDept string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                   // PIC X len=1 = "N"
var WsFirstFlag string = "Y"                 // PIC X len=1 = "Y"
var WsPrevDept string = "   "                // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal = decimal.Zero // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal = decimal.Zero  // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal = decimal.Zero   // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal = decimal.Zero // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 = 0                    // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal = decimal.Zero // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 = 0                      // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string  // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string  // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var empRec EmpRec
var empLines []string
var empIdx int

func isInputDone() bool  { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func countPlaceholders(p string) int {
	c := 0
	for _, ch := range p {
		if ch == 'Z' || ch == '9' {
			c++
		}
	}
	return c
}
func int64Pow(n int) int64 {
	if n <= 0 {
		return 1
	}
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}
func parsePicNumber(s string, scale int) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	var b strings.Builder
	hasSign := false
	for i, r := range s {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		} else if r == '-' && i == 0 {
			b.WriteRune(r)
			hasSign = true
		}
	}
	_ = hasSign
	clean := b.String()
	if clean == "" || clean == "-" {
		return decimal.Zero
	}
	// try int64 parse
	i, err := strconv.ParseInt(clean, 10, 64)
	if err == nil {
		return decimal.New(i, int32(-scale))
	}
	d, err2 := decimal.NewFromString(clean)
	if err2 == nil {
		return d.Shift(int32(-scale))
	}
	return decimal.Zero
}
func putDecimal(val decimal.Decimal, intDigits, scale int, rounded bool) decimal.Decimal {
	var adj decimal.Decimal
	if rounded {
		adj = val.Round(int32(scale))
	} else {
		adj = val.Truncate(int32(scale))
	}
	exp := intDigits + scale
	pow10 := decimal.New(1, int32(exp))
	scaled := adj.Shift(int32(scale))
	rem := scaled.Mod(pow10)
	result := rem.Shift(int32(-scale))
	return result
}
func putInt(val int64, digits int) int64 {
	mod := int64Pow(digits)
	r := val % mod
	if r < 0 {
		r += mod
	}
	return r
}
func formatInt(v int64, digits int) string {
	mod := int64Pow(digits)
	r := v % mod
	if r < 0 {
		r += mod
	}
	return fmt.Sprintf("%0*d", digits, r)
}
func formatEdited(val decimal.Decimal, pic string) string {
	parts := strings.Split(pic, ".")
	intPic := parts[0]
	decDigits := 0
	if len(parts) > 1 {
		decDigits = countPlaceholders(parts[1])
	}
	intDigits := countPlaceholders(intPic)

	adj := val.Truncate(int32(decDigits))
	absAdj := adj.Abs()

	scaled := absAdj.Shift(int32(decDigits))
	scaledInt := scaled.IntPart()

	pow10Dec := int64Pow(decDigits)
	var integerPart int64
	var fracPart int64
	if decDigits > 0 {
		integerPart = scaledInt / pow10Dec
		fracPart = scaledInt % pow10Dec
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		integerPart = scaledInt
		fracPart = 0
	}
	pow10Int := int64Pow(intDigits)
	integerPartMod := integerPart % pow10Int
	if integerPartMod < 0 {
		integerPartMod += pow10Int
	}
	intDigitsStr := fmt.Sprintf("%0*d", intDigits, integerPartMod)

	out := make([]rune, len(intPic))
	digitIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			out[i] = rune(intDigitsStr[digitIdx])
			digitIdx++
		} else if ch == ',' {
			out[i] = ','
		} else {
			out[i] = ch
		}
	}
	suppressed := true
	for i, ch := range intPic {
		if ch == 'Z' {
			if suppressed && out[i] == '0' {
				out[i] = ' '
			} else {
				suppressed = false
			}
		} else if ch == '9' {
			suppressed = false
		} else if ch == ',' {
			if suppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	intFormatted := string(out)
	decFormatted := ""
	if decDigits > 0 {
		fracStr := fmt.Sprintf("%0*d", decDigits, fracPart)
		decFormatted = "." + fracStr
	}
	return intFormatted + decFormatted
}

// paragraphs

func ReadPara() {
	if empIdx >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIdx]
	empIdx++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	empRec.ErId = line[0:5]
	empRec.ErDept = line[5:8]
	empRec.ErHours = parsePicNumber(line[8:12], 1)
	empRec.ErRate = parsePicNumber(line[12:17], 2)
}

func PayPara() {
	if empRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = putDecimal(decimal.NewFromInt(40), 3, 1, false)
		diff := empRec.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = putDecimal(diff, 3, 1, false)
	} else {
		WsRegHours = putDecimal(empRec.ErHours, 3, 1, false)
		WsOtHours = putDecimal(decimal.Zero, 3, 1, false)
	}
	onePointFive := decimal.New(15, -1)
	expr := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(onePointFive))
	WsGross = putDecimal(expr, 7, 2, true)
	WsDeptTotal = putDecimal(WsDeptTotal.Add(WsGross), 9, 2, false)
	WsDeptCount = putInt(WsDeptCount+1, 3)
	WsGrandTotal = putDecimal(WsGrandTotal.Add(WsGross), 11, 2, false)
	WsGrandCount = putInt(WsGrandCount+1, 5)

	WsHoursEd = formatEdited(empRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(empRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	line := empRec.ErId + " " + empRec.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd
	fmt.Fprintln(os.Stdout, line)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatInt(WsDeptCount, 3)
	line := "  DEPT " + WsPrevDept + " EMPLOYEES: " + countStr + " TOTAL: " + WsDeptEd
	fmt.Fprintln(os.Stdout, line)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatInt(WsGrandCount, 5)
	line := "GRAND TOTAL (" + countStr + "): " + WsGrandEd
	fmt.Fprintln(os.Stdout, line)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func MainPara() {
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	GrandPara()
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	empLines = lines
	empIdx = 0
	MainPara()
}
